import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from maze_evolution.dormant_evolution import OUT,check

def main():
 check();assert not (OUT/'report.md').exists()
 def read(name):return json.loads((OUT/name).read_text())
 s=read('summary.json');d=read('saved_diagnostics.json');a=read('allocation_persistence.json');p=read('preservation.json');n=read('neutral_birth.json');policy=s['policy_comparison'];sessions={k:read(v) for k,v in [('search','session.json'),('final','final_session.json')]};audits={k:read(k+'_audit.json') for k in sessions};assert all(v['status']=='PASS' for v in audits.values())
 lines=['# M23: selected evolution of disabled-at-birth branches','',f"Completed {sessions['search']['new_rounds']} matched rounds across nine96-slot populations; normal stop `{sessions['search']['stop']['reason']}`. Registered descriptive support for both contrasts: **{policy['descriptive_support_both']}**. No final-data reselection.",'',f"Registration `{read('launch.json')['registration_commit']}` and exact choices `{read('choices_freeze.json')['commit']}` were published before search and before fresh1,680-input confirmation respectively. Both audits passed.",'','## Fixed primary endpoint','',policy['primary']+'.','', 'Each nonempty exact-root AND phase-entry pair/corridor/ordinary/correct-no-path set must retain90%; A0 correct disconnection must be nonempty and90% retained; zero false reachable no-path and positive M23 mutation count. Novelty excludes the complete historical comparison archive plus root/entry/protected. Each contrast requires positive differences in2/3trios and positive sum. Descriptive only; no role switching or significance test.','', '| Trio | Ordinary | Enabled | Disabled | Disabled − enabled | Disabled − ordinary |','|---|---:|---:|---:|---:|---:|']
 for q in policy['pairs']:lines.append(f"| {q['replicate']} | {q['ordinary']} | {q['enabled']} | {q['disabled']} | {q['disabled_minus_enabled']} | {q['disabled_minus_ordinary']} |")
 lines+=['',f"Disabled vs enabled: `{json.dumps(policy['disabled_vs_enabled'])}`. Disabled vs ordinary: `{json.dumps(policy['disabled_vs_ordinary'])}`.",'','| Condition/role | Identity | M23/inherited births | Pairs | Corridors | Ordinary both poses | Correct no-path | False | Novel target pairs | Gate |','|---|---|---:|---:|---:|---:|---:|---:|---:|---|']
 for c in s['conditions']:
  v=c['metrics'];lines.append(f"| {c['condition']}/{c['role']} | {c['child']} | {c['mutations']}/{c['inherited_mutations']} | {v['paired']} | {v['by_domain']['corridor']['optimal']} | {v['ordinary_bases_both_poses']} | {v['correct_no_path']} | {v['false_no_path']} | {c['beyond_root_and_protected_union']['new_upstream_pairs']} | {c['retention_and_disconnection_gate']} |")
 lines+=['','## What was tested','', 'New matched forks from14preserved random-origin references, including exact M15 child/actual parent and the declared historical M10 threshold entry;82clones cycle the three focal bodies. Three related trios are not independent origins or continuation of whole old populations. Per round44survivors,7random immigrants and45one-opportunity mutants. All use the common exploratory selector, fresh48+fixed48training inputs and frozen M11 development bank assessment every16rounds. Equal96×96train and115×392assessment nominal allocations include nonselectable padding; physical dedup and CPU are separate.','', 'Ordinary uses the old generic operator. Both expression arms use25% three-node extension,25% syntactic wrapper tuning with generic fallback,50% ordinary. Extension activation/payload/SELECT preserve old private expressions. Only birth activation differs: CONST1 vs CONST0; payload is gated by activation and generic50% old-private COPY/50% random primitive. Tuning replaces a generic local activation or payload expression under selection. No oracle, case identifier, known solver, new runtime primitive or recombination enters inference. Only listed14sources breed; complete historical archive is comparison-only.','', 'The runtime remains EXACT M18 ten-channel VM:256ticks/256genome instructions,31nodes/block,4096reads/site,32768dispatches/site. Common append admission at<=128total instructions guarantees full256tick dispatch headroom. Generic mutations retain256cap and can block future insertion. This is a capacity restriction of this neutral operator, not arbitrary neutral growth; all no-op opportunities and extra costs are charged.','',f"Pre-registration neutral gate: {n['input_comparisons']:,} old-input comparisons across48insertions, all raster/status/ticks/reads equal;{n['passive_full_state_history_checks']} full-state history comparisons. Added memory84bytes/model; work increase range "+str([round(min(v['new_work']/v['old_work']-1 for v in n['embedding_costs'].values())*100,3),round(max(v['new_work']/v['old_work']-1 for v in n['embedding_costs'].values())*100,3)])+'%. Old excluded development fixtures, not confirmation or a speed benchmark.','', '## Novelty, losses and persistence','', f"{d['nominee_aliases']} roles represent {d['nominee_identities']} identities/{d['nominee_genotypes']} genotypes. Roles and aliases are not independent discoveries. Full root/parent/entry/frozen comparisons, correct-no-path gains/losses and ordinary length strata are in summary.json. All reference and candidate comparisons use identical final cases; raw changes across panels are not acquisition.",'','| Nominee | M23 edit kinds | Novel individual inputs | Novel ordinary routes | Correct16+ / available | Current wrappers / zero constants | Archive exact profile matches |','|---|---|---:|---|---:|---:|---:|']
 for identity,x in d['nominees'].items():
  v=d['model_details'][identity];t=x['structure'];lines.append(f"| {identity} | {json.dumps(x['phase_edit_kinds'])} | {len(x['new_individual_inputs_beyond_archive'])} | {[(z['family'],z['size'],z['edges']) for z in x['new_ordinary_details']]} | {v['length16plus_successes']}/{v['length16plus_bases']} | {t['recognized_wrappers']}/{t['recognized_const_zero_wrappers']} | {len(x['exact_archive_terminal_profiles'])} |")
 lines+=['', 'Extension ancestry and syntactic wrappers do not establish active routing or causal contribution. Upstream acquisition needs8novel target pairs/2contexts; long acquisition needs4new8+edge ordinary bases including16+and both perfect/random families. Both retain primary gates. Strict old-parent/specialist integration is separate. Useful specialist responses must be assessed with their losses.','', '| Population | Extension/tuning/no-op counts | Max M23 depth | Max extensions/chain | Extension descendants live/archive |','|---|---|---:|---:|---:|']
 for name,f in a['final_persistence'].items():
  counts={k:v for k,v in a['phase_edit_kinds'][name].items() if 'extension' in k or 'expression_edit' in k or k=='bounded_noop'};lines.append(f"| {name} | {json.dumps(counts)} | {f['max_M23_mutation_depth']} | {f['max_extension_births_on_chain']} | {f['extension_descendants']} |")
 lines+=['',f"Actual births: `{json.dumps(d['birth_counts'])}`. Opportunity/tuning-fallback/no-op counts, next-training survival, all final structures and shared physical cost buckets are preserved in allocation_persistence.json and search_audit.json. Remaining descendants do not prove cumulative algorithm construction.",'','## Costs, verification and preservation','', '| Phase | Physical calls | Candidate seconds | Worker CPU seconds | Wall seconds | Counted work | Peak RSS GiB |','|---|---:|---:|---:|---:|---:|---:|']
 for k,v in sessions.items():
  u=v['usage'];lines.append(f"| {k} | {u['calls']:,} | {u['candidate_seconds']:.2f} | {u['cpu_seconds']:.2f} | {v['wall_seconds']:.2f} | {u['work']:,} | {v['rss_peak_bytes']/2**30:.3f} |")
 lines+=['', 'Ten local CPU workers on Apple M4/16GiB, no cloud. Search70minsoft/90minhard,1024round/120Mcalls/1e15work;8GiBRSS/12GiBtotal inclbackups/16GiBfree. Final900s/1Mcalls/1e14work; each audit3600s. Timings are accounting, not repeated warm latency benchmarks. Guard/error stops require diagnosis, never automatic bound extension or failed resume.','', f"First search audit PASS: ALL{audits['search']['independent_grades']:,} grades/{audits['search']['native_replays']:,} native samples/{audits['search']['births_replayed']:,} births/{audits['search']['stages']} corpus/task/selection/mutation/RNG/freeze stages,{audits['search']['wall_seconds']:.2f}s. First final PASS: ALL{audits['final']['native_replays']:,} native outputs/grades/metrics and{audits['final']['conventional_calls']:,} BFS/A*/bitwave checks,{audits['final']['wall_seconds']:.2f}s. Intact controls all correct. Same production VM/operator, independent raster grader, not a second full VM.",'', 'Five focused preparation tests passed, not full historical suite. Artificial rehearsal312624calls/266.56candidate seconds/1404births; complete discarded pipeline35280final native calls and35280final-audit replays plus5040baselines. Neutral check85680native calls/79.00candidate seconds plus576passive executions. Initial cost-report helper failed after85680inferences; receipts/timing unavailable from that attempt, not claimed zero cost; traceback and correction preserved. Temporary postprocessing fixture initially used an out-of-project path; corrected fixture ROOT, no production change. Saved diagnostics and ALL-table SQLite backup fixture pass. No new preparation layouts.','',f"Uncertain attempts search/final: {sessions['search']['usage']['uncertain_attempts']}/{sessions['final']['usage']['uncertain_attempts']}. Whole excluded layouts {p['whole_layouts']:,} = {p['initial_layouts']:,} initial +{p['search_new_layouts']:,} search +{p['final_new_layouts']:,} final. All generated/rejected/unqueried layouts included. Use recursive verified reference+delta manifest; immutable bases required, raw layouts table is delta only.",'',f"Preservation status {p['status']}; SQLite-API backups under locks/ALL tables compared, originals retained. Phase storage {p['storage_bytes']/2**30:.3f}GiB, free{p['disk_free_bytes']/2**30:.2f}GiB before report/seal. Compact evidence/copied logs sealed and published; raw SQLite excluded from Git. All registered/prior hashes must verify at seal.",'', 'No general-solver, speed, significance or independent-origin claim. Review actual results and append interpretation/next recommendation before sealing. A bounded negative result does not close random-origin research. No phase beyond M23 launched.','']
 (OUT/'report.md').write_text('\n'.join(lines));print('M23 report drafted, actual interpretation review required')
if __name__=='__main__':main()
